window.rosewoodPolicyDocuments = Object.freeze({"enrolment-policy":{"slug":"enrolment-policy","title":"Enrolment Policy","sourceFile":"rosewood-policies/enrolment-policy-rosewood-college.docx","sourcePdf":"rosewood-policies/enrolment-policy-rosewood-college.pdf","sourceSha256":"e4f59b3928a36f98dc38392ca33ddef599bdca4be7c84eefa6a23dac5d91ca2a","sourceTextSha256":"3d31c7d244631268adeb239554627313b6ad398bf1fc255918d8bfdbef4f06b1","headings":[{"level":3,"number":"1","title":"Purpose","id":"policy-section-1-purpose"},{"level":3,"number":"2","title":"Scope","id":"policy-section-2-scope"},{"level":3,"number":"3","title":"Enrolment Principles","id":"policy-section-3-enrolment-principles"},{"level":3,"number":"4","title":"Eligibility and Enrolment Criteria","id":"policy-section-4-eligibility-and-enrolment-criteria"},{"level":4,"number":"4.1","title":"Eligibility for Enrolment","id":"policy-section-4-1-eligibility-for-enrolment"},{"level":4,"number":"4.2","title":"Selection where Places Are Limited","id":"policy-section-4-2-selection-where-places-are-limited"},{"level":3,"number":"5","title":"Enrolment Process Overview","id":"policy-section-5-enrolment-process-overview"},{"level":3,"number":"6","title":"Enrolment Agreements","id":"policy-section-6-enrolment-agreements"},{"level":3,"number":"7","title":"Required Documentation","id":"policy-section-7-required-documentation"},{"level":3,"number":"8","title":"Appeals","id":"policy-section-8-appeals"},{"level":3,"number":"9","title":"Privacy and Information Collection","id":"policy-section-9-privacy-and-information-collection"},{"level":3,"number":"10","title":"Enrolment Register","id":"policy-section-10-enrolment-register"},{"level":3,"number":"11","title":"Enrolment Administration","id":"policy-section-11-enrolment-administration"},{"level":3,"number":"12","title":"Implementation","id":"policy-section-12-implementation"},{"level":3,"number":"13","title":"Review","id":"policy-section-13-review"},{"level":3,"number":"14","title":"Related Documents","id":"policy-section-14-related-documents"}],"html":"<div class=\"policy-table-wrap policy-register-wrap\"><table class=\"policy-register\"><caption>Document register</caption><tbody><tr><th scope=\"row\">Document</th><td>Enrolment Policy</td></tr><tr><th scope=\"row\">Document Type</th><td>Policy</td></tr><tr><th scope=\"row\">Owner</th><td>Principal</td></tr><tr><th scope=\"row\">Approval Authority</th><td>Governing Authority</td></tr><tr><th scope=\"row\">Version</th><td>1.0</td></tr><tr><th scope=\"row\">Status</th><td>approved</td></tr><tr><th scope=\"row\">Approval Date</th><td>06 Apr 2026</td></tr><tr><th scope=\"row\">Review Cycle</th><td>3 years</td></tr><tr><th scope=\"row\">Next Review</th><td>06 Apr 2029</td></tr></tbody></table></div><h3 id=\"policy-section-1-purpose\"><span aria-hidden=\"true\">1. </span>Purpose</h3><p>The purpose of this policy is to establish the principles and criteria governing the enrolment of students at Rosewood College.</p><p>This policy ensures that enrolment decisions are made in a fair, transparent and lawful manner that is consistent with the philosophy and mission of the College and compliant with all applicable State and Commonwealth legislation, including laws relating to discrimination, equal opportunity, privacy, immunisation, reasonable adjustments and the Australian Consumer Law.</p><p>The policy defines the eligibility criteria for enrolment as a domestic student, the principles that guide enrolment decisions, and the authority responsible for making those decisions. It also outlines the College’s commitment to ensuring that enrolment practices respect the dignity of each student and support the educational philosophy and religious ethos of the College.</p><p>Detailed operational steps for managing enrolment enquiries, applications and offers are set out in the Enrolment Procedure and related operational documents.</p><h3 id=\"policy-section-2-scope\"><span aria-hidden=\"true\">2. </span>Scope</h3><p>This policy applies to all applications for enrolment at Rosewood College and applies to domestic students seeking admission to the College.</p><p>The policy applies to members of the school community involved in enrolment decisions and administration, including the Governing Authority, the Principal, and designated College staff responsible for managing the enrolment process.</p><p>The policy establishes the principles and criteria used to determine eligibility for enrolment, including any lawful preference given to families who support the religious ethos and educational philosophy of the College, as permitted under Schedule 4 clause 8 of the Education and Training Reform Regulations 2017.</p><p>This policy applies to all stages of the enrolment lifecycle, including the assessment of applications, offers of enrolment, enrolment agreements and the maintenance of enrolment records.</p><p>Operational procedures describing the steps in the enrolment process, required documentation and administrative responsibilities are defined in the Enrolment Procedure and related operational documents.</p><h3 id=\"policy-section-3-enrolment-principles\"><span aria-hidden=\"true\">3. </span>Enrolment Principles</h3><p>Rosewood College seeks to enrol students and families who support the educational philosophy, mission and values of the College, and may give preference in enrolment to families who adhere to the Catholic faith and the educational philosophy of the College, where permitted by law.</p><p>All enrolment decisions are made in accordance with applicable State and Commonwealth legislation, including laws relating to anti-discrimination, equal opportunity, privacy, immunisation and the duty to make reasonable adjustments for students with disabilities.</p><p>Rosewood College operates with a limited number of places available each year and does not guarantee enrolment. Where the number of applications exceeds the available places, enrolment decisions are made according to the principles set out in this policy. The extent to which a family supports the educational philosophy of the College may be considered in enrolment decisions, particularly where demand exceeds available places.</p><p>Offers of enrolment are made at the discretion of the Principal, having regard to the available places and the best interests of the student and the school community.</p><h3 id=\"policy-section-4-eligibility-and-enrolment-criteria\"><span aria-hidden=\"true\">4. </span>Eligibility and Enrolment Criteria</h3><h4 id=\"policy-section-4-1-eligibility-for-enrolment\"><span aria-hidden=\"true\">4.1. </span>Eligibility for Enrolment</h4><p>As an independent school that teaches the Catholic faith, Rosewood College enrols domestic students who meet the requirements for enrolment in a registered school in Victoria and whose families are willing to support the educational philosophy of the College.</p><p>To be eligible for enrolment, a student must:</p><ul><li>be eligible to attend a registered school in Victoria in accordance with applicable legislation</li><li>be a domestic student entitled to enrol in an Australian school</li><li>meet the age requirements for the relevant year level</li><li>provide documentation required by the College to establish identity, age, and eligibility for enrolment</li><li>meet any applicable health or immunisation requirements as required by law</li><li>have parents or guardians who acknowledge and are willing to support the educational philosophy of the College, including its approach to the formation of the student in accordance with the Catholic faith and moral tradition</li></ul><p>Eligibility for enrolment does not guarantee the offer of a place, and Rosewood College may require parents or guardians to provide information necessary to assess an application for enrolment, including information relevant to the student’s educational needs, wellbeing, and any adjustments that may be required to meet the needs of the student.</p><p>Where a student has a disability or additional learning or wellbeing needs, Rosewood College considers whether reasonable adjustments can be made to support the student’s participation in the educational program, and whether those adjustments can be reasonably provided by Rosewood College, in accordance with the Disability Discrimination Act 1992 (Cth) and the Disability Standards for Education 2005 (Cth).</p><h4 id=\"policy-section-4-2-selection-where-places-are-limited\"><span aria-hidden=\"true\">4.2. </span>Selection where Places Are Limited</h4><p>Where the number of eligible applicants exceeds the number of available places, enrolment offers are determined through consideration of the following:</p><ul><li>the date of application and availability of places</li><li>the capacity of the College to meet the educational and wellbeing needs of the student, including any requirement for reasonable adjustments</li><li>the extent to which the student and their family supports the educational philosophy of the College, as an independent school that teaches the Catholic faith</li><li>whether siblings of the applicant are currently enrolled at the College</li><li>the relationship of the applicant’s family to the school community</li><li>the willingness of the family to make a contribution to the broader life of the College</li></ul><p>As a school teaching the Catholic faith, Rosewood College may give preference in enrolment to students and families who adhere to, or actively support, the religious ethos and educational philosophy of the College, where permitted under Schedule 4, clause 8 of the Education and Training Reform Regulations 2017 (Vic).</p><p>This preference is applied as one factor among others when the number of eligible applicants exceeds the places available, and no single factor is determinative.</p><h3 id=\"policy-section-5-enrolment-process-overview\"><span aria-hidden=\"true\">5. </span>Enrolment Process Overview</h3><p>The College establishes enrolment timelines each year, including application opening periods, assessment timeframes and offer dates. These are communicated to prospective families and are set out in the Enrolment Procedure and related communications.</p><p>Enrolment applications are generally accepted throughout the year, with formal intake periods determined by the College. Applications for enrolment are typically invited from the end of Term 2 for the following academic year, with assessment and offers made on a rolling basis.</p><p>The enrolment process at Rosewood College is conducted in accordance with the Enrolment Procedure and generally includes the following stages:</p><ul><li>enquiry and provision of information to prospective families</li><li>submission of an application for enrolment</li><li>assessment of the application, which may include interviews and review of supporting documentation</li><li>decision-making by the Principal, who is responsible for determining enrolment outcomes in accordance with this policy</li><li>communication of the outcome, including any offer of enrolment</li><li>acceptance of an offer and completion of enrolment documentation</li></ul><p>Detailed operational steps and requirements are set out in the Enrolment Procedure.</p><h3 id=\"policy-section-6-enrolment-agreements\"><span aria-hidden=\"true\">6. </span>Enrolment Agreements</h3><p>Parents or guardians of each student enrolled at Rosewood College must enter into a formal enrolment agreement with the College.</p><p>The enrolment agreement sets out the rights and responsibilities of the College and the student’s parents or guardians and ensures that relevant legal and regulatory obligations are clearly documented.</p><p>The enrolment agreement may include information relating to:</p><ul><li>the educational services provided by the College</li><li>applicable College fees and charges</li><li>expectations of parents and guardians, including the Parent Code of Conduct</li><li>relevant College policies that apply to students and families</li><li>the circumstances under which the agreement may be terminated by either party.</li></ul><p>The enrolment agreement is provided to families prior to the confirmation of enrolment and must be signed by the parents or guardians before the student’s place at the College is secured.</p><h3 id=\"policy-section-7-required-documentation\"><span aria-hidden=\"true\">7. </span>Required Documentation</h3><p>To support enrolment, families are required to provide documentary evidence to verify the student’s identity, eligibility for enrolment and any relevant wellbeing or educational needs. This includes:</p><ul><li>the student’s birth certificate or other proof of identity</li><li>evidence of Australian citizenship, permanent residency or other lawful entitlement to attend school in Australia</li><li>an Immunisation History Statement from the Australian Immunisation Register, as required by law and to support the College’s health, safety, and duty of care obligations</li></ul><p>Additional documentation may be required to support the assessment of an application, including:</p><ul><li>previous school reports or educational records</li><li>any relevant medical information that may affect the student’s participation in school activities</li><li>copies of court orders, parenting plans or custody arrangements where applicable.</li></ul><p>Detailed requirements for documentation, including formats, timing and submission processes, are set out in the Enrolment Procedure and enrolment application materials.</p><h3 id=\"policy-section-8-appeals\"><span aria-hidden=\"true\">8. </span>Appeals</h3><p>A parent or guardian may request a review of an enrolment decision by submitting a written request to the Principal within a reasonable timeframe of being notified of the decision.</p><p>The review is conducted by the Governing Authority or its delegate, having regard to this policy and the information available at the time of the original decision.</p><p>The outcome of the review is communicated to the applicant, and the decision following review is final.</p><h3 id=\"policy-section-9-privacy-and-information-collection\"><span aria-hidden=\"true\">9. </span>Privacy and Information Collection</h3><p>Rosewood College collects personal and sensitive information about students and their families as part of the enrolment process and ongoing provision of education.</p><p>This information is collected, used and disclosed in accordance with applicable privacy legislation and the College’s Privacy Policy.</p><p>At the point of enrolment, families are provided with a Privacy Collection Notice which explains:</p><ul><li>the types of personal and sensitive information collected</li><li>the purposes for which the information is collected</li><li>how the information may be used and disclosed, including disclosure to government authorities for national and state data collection requirements</li><li>how the College stores and protects personal information</li><li>how individuals may access and correct their information</li></ul><p>The College’s Privacy Policy provides further information about how personal information is managed.</p><h3 id=\"policy-section-10-enrolment-register\"><span aria-hidden=\"true\">10. </span>Enrolment Register</h3><p>Rosewood College maintains a register of all students enrolled at the College.</p><p>The enrolment register is maintained in the College’s student management system and is kept up to date by designated College staff.</p><p>The register is maintained in accordance with applicable legislation and regulatory requirements relating to student records.</p><h3 id=\"policy-section-11-enrolment-administration\"><span aria-hidden=\"true\">11. </span>Enrolment Administration</h3><p>Rosewood College maintains procedures governing the administration of enrolment enquiries, applications, and offers of enrolment.</p><p>These procedures support the implementation of this policy and ensure that enrolment decisions are made consistently and transparently.</p><p>Operational steps relating to the enrolment process are described in the Enrolment Procedure and the Enrolment Process documents.</p><h3 id=\"policy-section-12-implementation\"><span aria-hidden=\"true\">12. </span>Implementation</h3><p>The Principal is responsible for implementing this policy and ensuring that enrolment practices at Rosewood College are consistent with the principles outlined in this document.</p><p>The Principal may delegate administrative responsibility for managing enrolment enquiries, applications, and records to designated College staff, including the Registrar or other authorised personnel.</p><p>All staff involved in enrolment administration must act in accordance with this policy and relevant legislation, including obligations relating to anti-discrimination, reasonable adjustments, privacy and student record keeping.</p><p>The operational processes used to manage enrolment enquiries, applications, interviews, offers of enrolment and enrolment agreements are set out in the Enrolment Procedure and associated operational documents.</p><p>The Governing Authority ensures that appropriate systems are in place to maintain accurate enrolment records and that enrolment decisions are consistent with the College’s philosophy, mission and values.</p><h3 id=\"policy-section-13-review\"><span aria-hidden=\"true\">13. </span>Review</h3><p>This policy will be reviewed at least every three years, or earlier if required due to changes in legislation, regulatory requirements, or the operational needs of the College.</p><p>The Principal is responsible for initiating the review of this policy and providing recommendations to the Governing Authority.</p><p>Any amendments to this policy must be approved by the Governing Authority.</p><p>The review process will consider:</p><ul><li>changes to relevant State or Commonwealth legislation</li><li>guidance issued by the Victorian Registration and Qualifications Authority</li><li>the effectiveness of the policy in supporting fair and transparent enrolment practices</li><li>feedback from families and staff involved in the enrolment process.</li></ul><p>The review date recorded in the document register will be updated following each approved revision.</p><h3 id=\"policy-section-14-related-documents\"><span aria-hidden=\"true\">14. </span>Related Documents</h3><p>Related documents include:</p><ul><li>Disability Discrimination Policy</li><li>Enrolment Procedure</li><li>Fee Policy</li><li>Privacy Collection Statement</li><li>Privacy Policy</li></ul>"},"enrolment-procedure":{"slug":"enrolment-procedure","title":"Enrolment Procedure","sourceFile":"rosewood-policies/enrolment-procedure-rosewood-college.docx","sourcePdf":"rosewood-policies/enrolment-procedure-rosewood-college.pdf","sourceSha256":"042abe1f25ccd8acfc640365ca3cfc4aaa5eb6ea5b25576e5d407e0d7778066f","sourceTextSha256":"5d8bc8720a8d14ee0f93cddfda752916ef14d4a642b4337039070eaf84cf641b","headings":[{"level":3,"number":"1","title":"Purpose","id":"policy-section-1-purpose"},{"level":3,"number":"2","title":"Scope","id":"policy-section-2-scope"},{"level":3,"number":"3","title":"Procedure","id":"policy-section-3-procedure"},{"level":4,"number":"3.1","title":"Enrolment Enquiries","id":"policy-section-3-1-enrolment-enquiries"},{"level":4,"number":"3.2","title":"Application for Enrolment","id":"policy-section-3-2-application-for-enrolment"},{"level":4,"number":"3.3","title":"Assessment of Applications","id":"policy-section-3-3-assessment-of-applications"},{"level":4,"number":"3.4","title":"Consultation and Interview (where Applicable)","id":"policy-section-3-4-consultation-and-interview-where-applicable"},{"level":4,"number":"3.5","title":"Enrolment Decision","id":"policy-section-3-5-enrolment-decision"},{"level":4,"number":"3.6","title":"Offer of Enrolment","id":"policy-section-3-6-offer-of-enrolment"},{"level":4,"number":"3.7","title":"Acceptance of Enrolment","id":"policy-section-3-7-acceptance-of-enrolment"},{"level":4,"number":"3.8","title":"Enrolment Agreement","id":"policy-section-3-8-enrolment-agreement"},{"level":4,"number":"3.9","title":"Deferral and Withdrawal","id":"policy-section-3-9-deferral-and-withdrawal"},{"level":4,"number":"3.10","title":"Lapsed Offers and Enrolment Progression","id":"policy-section-3-10-lapsed-offers-and-enrolment-progression"},{"level":4,"number":"3.11","title":"Enrolment Decision Appeal","id":"policy-section-3-11-enrolment-decision-appeal"},{"level":4,"number":"3.12","title":"Administrative Responsibilities","id":"policy-section-3-12-administrative-responsibilities"},{"level":4,"number":"3.13","title":"Enrolment Status","id":"policy-section-3-13-enrolment-status"},{"level":4,"number":"3.14","title":"Collection and Management of Information","id":"policy-section-3-14-collection-and-management-of-information"},{"level":4,"number":"3.15","title":"Enrolment Records and Register","id":"policy-section-3-15-enrolment-records-and-register"},{"level":3,"number":"4","title":"Implementation","id":"policy-section-4-implementation"},{"level":3,"number":"5","title":"Review","id":"policy-section-5-review"},{"level":3,"number":"6","title":"Related Documents","id":"policy-section-6-related-documents"}],"html":"<div class=\"policy-table-wrap policy-register-wrap\"><table class=\"policy-register\"><caption>Document register</caption><tbody><tr><th scope=\"row\">Document</th><td>Enrolment Procedure</td></tr><tr><th scope=\"row\">Document Type</th><td>Procedure</td></tr><tr><th scope=\"row\">Owner</th><td>Principal</td></tr><tr><th scope=\"row\">Approval Authority</th><td>Principal</td></tr><tr><th scope=\"row\">Version</th><td>1.0</td></tr><tr><th scope=\"row\">Status</th><td>approved</td></tr><tr><th scope=\"row\">Approval Date</th><td>25 Apr 2026</td></tr><tr><th scope=\"row\">Review Cycle</th><td>2 years</td></tr><tr><th scope=\"row\">Next Review</th><td>25 Apr 2028</td></tr></tbody></table></div><h3 id=\"policy-section-1-purpose\"><span aria-hidden=\"true\">1. </span>Purpose</h3><p>This procedure sets out the process for managing student enrolment at Rosewood College, including the handling of enquiries, applications, assessment, offers, and acceptance of enrolment.</p><p>This procedure supports and implements the Enrolment Policy and ensures that enrolment practices are conducted in a consistent, fair, and transparent manner, and in accordance with applicable legislative requirements.</p><p>This procedure ensures that enrolment decisions are applied consistently, that appropriate information is obtained to support decision-making, and that accurate records of enrolment are maintained.</p><p>This procedure supports compliance with applicable State and Commonwealth legislation, including laws relating to discrimination, privacy, and student enrolment requirements.</p><h3 id=\"policy-section-2-scope\"><span aria-hidden=\"true\">2. </span>Scope</h3><p>This procedure applies to all staff involved in the administration and management of student enrolment at Rosewood College, including the Principal and any staff delegated responsibility for enrolment processes.</p><p>This procedure applies to all applications for enrolment of domestic students and covers all stages of the enrolment lifecycle, including initial enquiries, application submission, assessment, decision-making, offers of enrolment, acceptance, and the creation and maintenance of enrolment records.</p><p>This procedure operates in conjunction with the Enrolment Policy and must be applied consistently in all enrolment-related activities.</p><h3 id=\"policy-section-3-procedure\"><span aria-hidden=\"true\">3. </span>Procedure</h3><p>The enrolment process at Rosewood College is managed through the following stages:</p><h4 id=\"policy-section-3-1-enrolment-enquiries\"><span aria-hidden=\"true\">3.1. </span>Enrolment Enquiries</h4><ul><li>All enrolment enquiries must be recorded and managed by the College.</li><li>Prospective families are to be provided with information about the College, its educational philosophy, the enrolment process, and relevant enrolment timelines.</li></ul><h4 id=\"policy-section-3-2-application-for-enrolment\"><span aria-hidden=\"true\">3.2. </span>Application for Enrolment</h4><ul><li>Applications must be submitted using the approved Enrolment Application Form.</li><li>Applicants must provide all required supporting documentation.</li><li>Incomplete applications may not be assessed until all required information has been provided.</li><li>The College may verify information and documentation provided as part of the application.</li></ul><p>Supporting documentation may include personal information, prior educational records, medical or well-being information, and any other information relevant to the student’s application.</p><h4 id=\"policy-section-3-3-assessment-of-applications\"><span aria-hidden=\"true\">3.3. </span>Assessment of Applications</h4><ul><li>Applications are to be assessed in accordance with the Enrolment Policy.</li><li>The College may request additional information where necessary to assess the application.</li><li>Consideration is given to:<ul><li>eligibility criteria</li><li>available number of places</li><li>the capacity of the College to meet the student’s educational and support needs, including the provision of reasonable adjustments where required by law</li><li>whether siblings of the applicant are currently enrolled at the College</li><li>the relationship of the family to the school community</li><li>the extent to which the family supports the educational philosophy, mission, values, and religious ethos of the College, where permitted by law</li></ul></li></ul><h4 id=\"policy-section-3-4-consultation-and-interview-where-applicable\"><span aria-hidden=\"true\">3.4. </span>Consultation and Interview (where Applicable)</h4><ul><li>The College may require an interview with the student and parents/carers as part of the enrolment assessment process.</li><li>The purpose of the interview is to:<ul><li>clarify information provided in the application</li><li>assess the family’s understanding of and alignment with the educational philosophy and expectations of the College</li><li>understand the student’s educational, pastoral, and support needs</li><li>determine the suitability of the enrolment</li></ul></li></ul><h4 id=\"policy-section-3-5-enrolment-decision\"><span aria-hidden=\"true\">3.5. </span>Enrolment Decision</h4><ul><li>Enrolment decisions are made by the Principal in accordance with the Enrolment Policy.</li><li>The College is not obliged to offer enrolment where places are limited or where, after reasonable consideration, the College determines that it cannot meet the needs of the student.</li></ul><h4 id=\"policy-section-3-6-offer-of-enrolment\"><span aria-hidden=\"true\">3.6. </span>Offer of Enrolment</h4><ul><li>Successful applicants will be provided with a formal Offer of Enrolment.</li><li>The offer will include:<ul><li>the Enrolment Agreement</li><li>relevant College policies and key information</li><li>any conditions of enrolment</li><li>the deadline for accepting the offer and completing enrolment requirements</li></ul></li></ul><h4 id=\"policy-section-3-7-acceptance-of-enrolment\"><span aria-hidden=\"true\">3.7. </span>Acceptance of Enrolment</h4><ul><li>Enrolment is confirmed only when:<ul><li>the Enrolment Agreement is signed and returned by the parent / guardian</li><li>any required fees are paid</li><li>any stated conditions of enrolment are met</li><li>any required forms and supporting information are provided</li></ul></li><li>Failure to meet these requirements within the timeframe specified in the Offer of Enrolment may, at the Principal’s discretion, result in the offer being withdrawn.</li></ul><h4 id=\"policy-section-3-8-enrolment-agreement\"><span aria-hidden=\"true\">3.8. </span>Enrolment Agreement</h4><p>Parents or guardians of each student enrolled at Rosewood College must enter into a formal Enrolment Agreement with the College.</p><p>The Enrolment Agreement sets out the rights and responsibilities of the College and the parents or guardians and may include fees and charges, expectations of families, relevant College policies, and the circumstances under which the agreement may be terminated by either party.</p><h4 id=\"policy-section-3-9-deferral-and-withdrawal\"><span aria-hidden=\"true\">3.9. </span>Deferral and Withdrawal</h4><p>A request to defer commencement or withdraw an application or accepted place must be made in writing by the parent or guardian. Requests for deferral will be considered by the Principal, having regard to place availability, intake timing, and the circumstances of the application.</p><p>Where a family withdraws after accepting an offer, any consequences will be managed in accordance with the Enrolment Agreement and any applicable College policies.</p><h4 id=\"policy-section-3-10-lapsed-offers-and-enrolment-progression\"><span aria-hidden=\"true\">3.10. </span>Lapsed Offers and Enrolment Progression</h4><p>The College may determine that an offer has lapsed, or may decline to proceed with an offer, where:</p><ul><li>required documentation has not been provided</li><li>information requested by the College has not been supplied within the required timeframe</li><li>requirements stated in the offer have not been completed</li><li>required fees or deposits have not been paid by the due date</li></ul><p>Where a place has already been secured through a signed Enrolment Agreement, any termination or withdrawal will be managed in accordance with the Enrolment Agreement and applicable College policies.</p><h4 id=\"policy-section-3-11-enrolment-decision-appeal\"><span aria-hidden=\"true\">3.11. </span>Enrolment Decision Appeal</h4><p>A parent or guardian may request a review of an enrolment decision by submitting a written request to the Principal within a reasonable timeframe of being notified of the decision.</p><p>The review is conducted by the Governing Authority or its delegate, having regard to this procedure and the information available at the time of the original decision.</p><p>The outcome of the review is communicated to the applicant, and the decision following review is final.</p><h4 id=\"policy-section-3-12-administrative-responsibilities\"><span aria-hidden=\"true\">3.12. </span>Administrative Responsibilities</h4><p>The Principal is responsible for implementing this procedure and ensuring that enrolment processes are conducted in accordance with the Enrolment Policy and applicable legal requirements.</p><p>The Principal may delegate responsibility for the administration of enrolment processes to designated staff or other authorised personnel.</p><p>Staff involved in enrolment administration must act in accordance with the Enrolment Policy, this procedure, privacy obligations, anti-discrimination requirements, obligations relating to reasonable adjustments, and student recordkeeping requirements.</p><p>For administrative and recordkeeping purposes, the College may use status descriptors such as applicant, offered, accepted, current, deferred, and withdrawn.</p><h4 id=\"policy-section-3-13-enrolment-status\"><span aria-hidden=\"true\">3.13. </span>Enrolment Status</h4><p>For administrative purposes, student enrolment status may be recorded as one of the following:</p><ul><li>Applicant – application received and under consideration</li><li>Offered – formal offer issued</li><li>Accepted – offer accepted and enrolment requirements being finalised</li><li>Current – student enrolled and attending the College</li><li>Deferred – offer accepted but commencement approved for a later date</li><li>Withdrawn – enrolment withdrawn by parent/carer before or after commencement</li></ul><h4 id=\"policy-section-3-14-collection-and-management-of-information\"><span aria-hidden=\"true\">3.14. </span>Collection and Management of Information</h4><ul><li>The College collects and manages enrolment information in accordance with applicable privacy and legislative requirements.</li><li>Information provided by parents/carers must be accurate, complete and current.</li><li>The College may require updated or additional information where necessary and ensures that enrolment information is accurate, complete and securely maintained.</li></ul><h4 id=\"policy-section-3-15-enrolment-records-and-register\"><span aria-hidden=\"true\">3.15. </span>Enrolment Records and Register</h4><ul><li>The Enrolment Register is maintained in accordance with regulatory requirements.</li><li>Records of enrolment, including applications, supporting documentation, assessment records, offers, acceptances and Enrolment Agreements, are retained as part of the student record.</li></ul><h3 id=\"policy-section-4-implementation\"><span aria-hidden=\"true\">4. </span>Implementation</h3><p>The Principal is responsible for the implementation of this procedure and for ensuring that enrolment processes are conducted in accordance with the Enrolment Policy and applicable legislative requirements.</p><p>The Principal may delegate responsibility for the administration of enrolment processes to appropriate staff. All staff involved in enrolment must apply this procedure consistently and maintain appropriate records to support enrolment decisions.</p><p>Enrolment processes are supported by appropriate systems, documentation and record-keeping practices, including the maintenance of an Enrolment Register and associated student records.</p><p>The Principal is responsible for monitoring the effective implementation of this procedure and ensuring that enrolment practices remain consistent, fair, and transparent.</p><h3 id=\"policy-section-5-review\"><span aria-hidden=\"true\">5. </span>Review</h3><p>This procedure will be reviewed at least every two years, or more frequently if required due to changes in legislation, regulatory requirements, or College operations.</p><p>The Principal is responsible for initiating and overseeing the review of this procedure and for recommending any required updates to ensure ongoing compliance and effective implementation.</p><h3 id=\"policy-section-6-related-documents\"><span aria-hidden=\"true\">6. </span>Related Documents</h3><p>Related documents include:</p><ul><li>Disability Discrimination Policy</li><li>Enrolment Agreement</li><li>Enrolment Application Form</li><li>Enrolment Policy</li><li>Fee Schedule</li><li>Offer of Enrolment</li><li>Privacy Collection Statement</li></ul>"},"privacy-policy":{"slug":"privacy-policy","title":"Privacy Policy","sourceFile":"rosewood-policies/privacy-policy-rosewood-college.docx","sourcePdf":"rosewood-policies/privacy-policy-rosewood-college.pdf","sourceSha256":"f0cde7768b7ab470a41f95885f409797aacb9f3154cc2e58332144aaa6f26823","sourceTextSha256":"df21a188ebbe89a70574021e7ae27c4c44206c8e5eee9d050382cf856cfe82cc","headings":[{"level":3,"number":"1","title":"Purpose","id":"policy-section-1-purpose"},{"level":3,"number":"2","title":"Scope","id":"policy-section-2-scope"},{"level":3,"number":"3","title":"Collection of Personal Information","id":"policy-section-3-collection-of-personal-information"},{"level":3,"number":"4","title":"Use and Disclosure of Personal Information","id":"policy-section-4-use-and-disclosure-of-personal-information"},{"level":3,"number":"5","title":"Storage and Security of Personal Information","id":"policy-section-5-storage-and-security-of-personal-information"},{"level":3,"number":"6","title":"Access to and Correction of Personal Information","id":"policy-section-6-access-to-and-correction-of-personal-information"},{"level":3,"number":"7","title":"Retention and Disposal of Personal Information","id":"policy-section-7-retention-and-disposal-of-personal-information"},{"level":3,"number":"8","title":"Privacy Statements","id":"policy-section-8-privacy-statements"},{"level":3,"number":"9","title":"Data Breaches","id":"policy-section-9-data-breaches"},{"level":3,"number":"10","title":"Complaints","id":"policy-section-10-complaints"},{"level":3,"number":"11","title":"Implementation","id":"policy-section-11-implementation"},{"level":3,"number":"12","title":"Review","id":"policy-section-12-review"},{"level":3,"number":"13","title":"Related Documents","id":"policy-section-13-related-documents"},{"level":3,"number":"14","title":"Appendix A: Full Privacy Collection Statement","id":"policy-section-14-appendix-a-full-privacy-collection-statement"},{"level":3,"number":"15","title":"Appendix B: Shortform Privacy Collection Statement","id":"policy-section-15-appendix-b-shortform-privacy-collection-statement"}],"html":"<div class=\"policy-table-wrap policy-register-wrap\"><table class=\"policy-register\"><caption>Document register</caption><tbody><tr><th scope=\"row\">Document</th><td>Privacy Policy</td></tr><tr><th scope=\"row\">Document Type</th><td>Policy</td></tr><tr><th scope=\"row\">Owner</th><td>Principal</td></tr><tr><th scope=\"row\">Approval Authority</th><td>Governing Authority</td></tr><tr><th scope=\"row\">Version</th><td>1.0</td></tr><tr><th scope=\"row\">Status</th><td>approved</td></tr><tr><th scope=\"row\">Approval Date</th><td>07 Apr 2026</td></tr><tr><th scope=\"row\">Review Cycle</th><td>3 years</td></tr><tr><th scope=\"row\">Next Review</th><td>07 Apr 2029</td></tr></tbody></table></div><h3 id=\"policy-section-1-purpose\"><span aria-hidden=\"true\">1. </span>Purpose</h3><p>The purpose of this policy is to set out the principles governing how Rosewood College collects, uses, stores, discloses, retains, and manages personal and sensitive information in the course of its operations.</p><p>This policy supports the College’s commitment to lawful, transparent and responsible information handling in accordance with applicable privacy legislation and related record-keeping obligations. It establishes the College’s expectations for the protection of personal information relating to current and prospective students, parents and guardians, staff, volunteers, contractors, service providers, and other members of the school community.</p><p>This policy also supports Rosewood College’s enrolment, student record management, child safety, wellbeing, governance, employment and administrative functions by providing a whole-of-school framework for privacy and information management.</p><h3 id=\"policy-section-2-scope\"><span aria-hidden=\"true\">2. </span>Scope</h3><p>This policy applies to all members of the school community, including:</p><ul><li>students and prospective students</li><li>parents, guardians and families</li><li>members of the Governing Authority</li><li>the Principal and all College staff</li><li>volunteers, contractors and service providers</li><li>any other individuals whose personal information is collected or held by the College</li></ul><p>This policy applies to all forms of personal information, whether collected directly from individuals or from third parties, and whether held in physical or electronic form.</p><p>This policy applies to all school activities, including enrolment, student administration, education and wellbeing, employment, governance, and operational functions.</p><h3 id=\"policy-section-3-collection-of-personal-information\"><span aria-hidden=\"true\">3. </span>Collection of Personal Information</h3><p>Rosewood College collects personal and sensitive information that is reasonably necessary for the conduct of its educational, administrative, and operational functions.</p><p>Personal information may be collected directly from individuals or their authorised representatives, or from third parties where permitted by law. This includes information collected during the enrolment process and throughout a student’s enrolment at the College.</p><p>The College collects personal information to:</p><ul><li>assess applications for enrolment</li><li>provide educational services and support student learning and wellbeing</li><li>communicate with students, families and the school community</li><li>meet legal, regulatory, and reporting obligations</li><li>ensure the safety, health, and wellbeing of students and staff</li></ul><p>Where required, the College provides a Privacy Collection Statement at or before the point of collection.</p><h3 id=\"policy-section-4-use-and-disclosure-of-personal-information\"><span aria-hidden=\"true\">4. </span>Use and Disclosure of Personal Information</h3><p>Rosewood College uses personal information for the primary purpose for which it was collected and for related purposes that would reasonably be expected.</p><p>The College may disclose personal information where permitted or required by law, including to:</p><ul><li>government departments and agencies for regulatory, funding, and reporting purposes</li><li>other educational institutions in connection with student transfers</li><li>health professionals and service providers to support student wellbeing</li><li>contractors and service providers engaged by the College</li><li>other parties where authorised or required by law</li></ul><p>The College does not disclose personal information for secondary purposes without consent unless permitted or required by law.</p><h3 id=\"policy-section-5-storage-and-security-of-personal-information\"><span aria-hidden=\"true\">5. </span>Storage and Security of Personal Information</h3><p>Rosewood College takes reasonable steps to protect personal information from misuse, interference, loss, unauthorised access, modification, or disclosure.</p><p>Reasonable steps may include:</p><ul><li>using device passwords or biometric security</li><li>keeping software up to date</li><li>avoiding unnecessary local copies</li><li>not sharing personal information through informal channels unless necessary</li><li>using blind copy for group emails where appropriate</li><li>limiting access to authorised persons</li><li>transferring records to an approved College system when available</li><li>deleting duplicate or unnecessary copies when no longer required</li></ul><p>Personal information is stored in secure physical and electronic systems with access limited to authorised personnel who require the information for legitimate College business purposes.</p><p>The College maintains appropriate data security practices through the following:</p><ul><li>controlled access to records and systems</li><li>staff training and awareness in privacy obligations</li><li>secure storage and record-keeping systems</li><li>processes to manage and review privacy risks; and</li><li>reasonable safeguards where information is transferred, hosted or stored using third-party systems or outside Victoria or Australia, where applicable</li></ul><p>Personal relationships with prospective families or supporters do not remove the need to protect personal information, respect confidentiality, limit use and disclosure to appropriate College purposes, and take reasonable steps to prevent unauthorised access, loss, misuse or disclosure.</p><h3 id=\"policy-section-6-access-to-and-correction-of-personal-information\"><span aria-hidden=\"true\">6. </span>Access to and Correction of Personal Information</h3><p>Individuals may request access to personal information held about them and request correction of information that is inaccurate, incomplete, or out of date.</p><p>Requests for access or correction must be made in accordance with the College’s procedures.</p><p>The College responds to such requests in accordance with applicable privacy legislation and may refuse access where permitted by law.</p><h3 id=\"policy-section-7-retention-and-disposal-of-personal-information\"><span aria-hidden=\"true\">7. </span>Retention and Disposal of Personal Information</h3><p>Rosewood College retains personal information in accordance with applicable legal, regulatory and record-keeping obligations and only for as long as necessary to fulfil the purposes for which it was collected or as otherwise required by law.</p><p>When personal information is no longer required, the College takes reasonable steps to securely destroy or de-identify the information, in accordance with applicable record retention and disposal requirements.</p><h3 id=\"policy-section-8-privacy-statements\"><span aria-hidden=\"true\">8. </span>Privacy Statements</h3><p>The College maintains appropriate privacy statements, collection notices, or related privacy information made available through relevant channels, including the College website where appropriate.</p><p>These statements explain, in general terms:</p><ul><li>the College’s functions and the kinds of personal information it collects</li><li>how that information is used and disclosed</li><li>whether the collection is required or authorised by law, where relevant</li><li>how the information is stored and protected</li><li>how individuals may request access or correction, or make a complaint</li></ul><h3 id=\"policy-section-9-data-breaches\"><span aria-hidden=\"true\">9. </span>Data Breaches</h3><p>Rosewood College maintains documented procedures for the identification, containment, assessment, escalation, notification, investigation and review of actual or suspected data breaches.</p><p>All actual or suspected data breaches must be reported immediately to the Principal or delegated Privacy Officer and recorded in the College’s incident management records.</p><p>Where required by law, affected individuals and relevant authorities are notified in accordance with applicable legislative obligations.</p><p>In the event of an eligible data breach, the College acts in accordance with the Notifiable Data Breaches scheme and any other applicable legal obligations, including notifying affected individuals and relevant authorities where required.</p><p>All staff, contractors and volunteers must promptly report any actual or suspected privacy breach or data breach in accordance with College procedures.</p><h3 id=\"policy-section-10-complaints\"><span aria-hidden=\"true\">10. </span>Complaints</h3><p>Complaints about the handling of personal information may be made in accordance with the College’s Complaints and Grievances Policy.</p><p>The College investigates and responds to complaints in a fair and timely manner. Where appropriate, individuals may refer complaints to the Office of the Australian Information Commissioner or other relevant regulatory authority.</p><h3 id=\"policy-section-11-implementation\"><span aria-hidden=\"true\">11. </span>Implementation</h3><p>The Governing Authority is responsible for approving this policy and any substantive amendments.</p><p>The Principal is responsible for the implementation of this policy and for ensuring that the College’s practices relating to the collection, use, storage, and management of personal information are consistent with this policy and applicable legislation.</p><p>The Principal may delegate responsibility for administering privacy and information management processes to designated College staff, including administrative and leadership personnel, and may appoint a Privacy Officer or other responsible staff member to assist with privacy compliance and complaint handling.</p><p>All staff, contractors, and volunteers who have access to personal information are required to:</p><ul><li>handle personal and sensitive information in accordance with this policy and applicable privacy legislation</li><li>maintain confidentiality and protect the privacy of individuals</li><li>take reasonable steps to ensure the accuracy and security of personal information</li><li>report any actual or suspected data breaches in accordance with College procedures</li><li>participate in privacy training or awareness activities as required</li></ul><p>The College implements appropriate systems, processes and training to support compliance with this policy.</p><h3 id=\"policy-section-12-review\"><span aria-hidden=\"true\">12. </span>Review</h3><p>This policy will be reviewed at least every three years, or earlier if required due to changes in legislation, regulatory requirements, technology, College operations, or privacy risks.</p><p>The Principal is responsible for initiating the review of this policy and providing recommendations to the Governing Authority.</p><p>Any amendments to this policy must be approved by the Governing Authority.</p><p>The review process will consider:</p><ul><li>changes to relevant State and Commonwealth privacy, health records and record-keeping legislation</li><li>guidance issued by regulatory authorities</li><li>the effectiveness of the College’s privacy and information management practices</li><li>any privacy incidents, complaints, or data breaches</li><li>feedback from members of the school community</li></ul><h3 id=\"policy-section-13-related-documents\"><span aria-hidden=\"true\">13. </span>Related Documents</h3><p>Related documents include:</p><ul><li>Complaints and Grievances Policy</li><li>Data Breach Response Procedure</li><li>Information Security Procedure</li><li>Records Management Policy</li></ul><h3 id=\"policy-section-14-appendix-a-full-privacy-collection-statement\"><span aria-hidden=\"true\">14. </span>Appendix A: Full Privacy Collection Statement</h3><p>Rosewood College collects personal and sensitive information for the primary purposes of assessing enrolment applications, determining eligibility for enrolment, considering any support or reasonable adjustments that may be required, providing educational services, supporting student wellbeing, and maintaining student records.</p><p>The information collected may include personal information about students and parents/guardians, as well as sensitive information such as health information, religious affiliation, and information relating to learning needs.</p><p>This information is collected in accordance with applicable privacy legislation, including the Privacy Act 1988 (Cth), the Privacy and Data Protection Act 2014 (Vic), and other relevant laws applicable to schools.</p><p>If the requested information is not provided, Rosewood College may be unable to assess an application for enrolment or provide appropriate educational and support services.</p><p>Personal information may be disclosed to relevant authorities and organisations where required or authorised by law, including government departments, regulatory authorities, health service providers, and service providers engaged by the College to support its operations.</p><p>Rosewood College takes reasonable steps to ensure that personal information is stored securely and protected from misuse, loss, unauthorised access, modification, or disclosure.</p><p>Parents and guardians may request access to, or correction of, personal information held by the College by contacting the College office or the Privacy Officer.</p><p>Further information about how Rosewood College manages personal information is available in the College’s Privacy Policy.</p><h3 id=\"policy-section-15-appendix-b-shortform-privacy-collection-statement\"><span aria-hidden=\"true\">15. </span>Appendix B: Shortform Privacy Collection Statement</h3><p>Rosewood College collects personal and sensitive information, including health information, to support the student’s health, safety and wellbeing and to enable the College to provide appropriate care and support.</p><p>This information may be disclosed to relevant staff and, where necessary, to health professionals or emergency services.</p><p>All information is handled in accordance with the College’s Privacy Policy and Privacy Collection Notice, which are available from the College.</p>"}});
